
const WORDS=[{"id": 0, "w": "悠久", "p": "yōujiǔ", "t": "形容词", "m": "lâu đời", "coll": "悠久的历史、悠久的文化", "s": "这座城市有着悠久的历史和丰富的文化。"}, {"id": 1, "w": "文字", "p": "wénzì", "t": "名词", "m": "văn tự (ngôn ngữ viết)", "coll": "中国文字、用文字记录", "s": "他用文字记录下了旅行中的见闻。"}, {"id": 2, "w": "记载", "p": "jìzǎi", "t": "动词", "m": "ghi chép, ghi lại", "coll": "详细记载、书中记载", "s": "这本书里详细记载了这座古城过去的生活。"}, {"id": 3, "w": "形状", "p": "xíngzhuàng", "t": "名词", "m": "hình dạng", "coll": "形状各异、不同的形状", "s": "这些石头的形状各不相同，看起来很有意思。"}, {"id": 4, "w": "描写", "p": "miáoxiě", "t": "动词", "m": "miêu tả", "coll": "描写景色、描写人物", "s": "这篇文章生动地描写了春天的景色。"}, {"id": 5, "w": "赞美", "p": "zànměi", "t": "动词", "m": "ca ngợi, ca tụng", "coll": "赞美家乡、赞美自然", "s": "这首歌表达了人们对家乡的赞美之情。"}, {"id": 6, "w": "诗", "p": "shī", "t": "名词", "m": "thơ", "coll": "一首诗、写诗", "s": "她为自己的家乡写了一首诗。"}, {"id": 7, "w": "老百姓", "p": "lǎobǎixìng", "t": "名词", "m": "người dân, thường dân", "coll": "普通老百姓、老百姓的生活", "s": "这项新政策给老百姓的生活带来了方便。"}, {"id": 8, "w": "充满", "p": "chōngmǎn", "t": "动词", "m": "chan chứa, tràn ngập", "coll": "充满希望、充满笑声", "s": "节日的广场上充满了孩子们的笑声。"}, {"id": 9, "w": "感激", "p": "gǎnjī", "t": "动词", "m": "cảm kích, biết ơn", "coll": "感激不尽、十分感激", "s": "对于你的帮助，我一直很感激。"}, {"id": 10, "w": "从而", "p": "cóng'ér", "t": "连词", "m": "do đó, vì vậy", "coll": "从而提高效率、从而解决问题", "s": "他调整了学习方法，从而提高了学习效率。"}, {"id": 11, "w": "产生", "p": "chǎnshēng", "t": "动词", "m": "sản sinh, xuất hiện", "coll": "产生兴趣、产生影响", "s": "这次旅行使我对当地的文化产生了兴趣。"}, {"id": 12, "w": "传说", "p": "chuánshuō", "t": "名词", "m": "truyền thuyết", "coll": "一个传说、民间传说", "s": "奶奶给我们讲了一个关于泉水的传说。"}, {"id": 13, "w": "善良", "p": "shànliáng", "t": "形容词", "m": "lương thiện, tốt bụng", "coll": "心地善良、善良的人", "s": "她心地善良，经常帮助有困难的人。"}, {"id": 14, "w": "救", "p": "jiù", "t": "动词", "m": "cứu, cứu giúp", "coll": "救人、救了一条命", "s": "他毫不犹豫地跳进水里，救起了那个孩子。"}, {"id": 15, "w": "晕", "p": "yūn", "t": "动词", "m": "hôn mê, bất tỉnh", "coll": "晕过去、突然晕倒", "s": "天气太热，他在路边晕了过去。"}, {"id": 16, "w": "龙", "p": "lóng", "t": "名词", "m": "rồng", "coll": "一条龙、龙的形象", "s": "这幅画上画着一条正在飞翔的龙。"}, {"id": 17, "w": "治疗", "p": "zhìliáo", "t": "动词", "m": "điều trị, chữa bệnh", "coll": "接受治疗、治疗疾病", "s": "医生正在为受伤的病人进行治疗。"}, {"id": 18, "w": "玉", "p": "yù", "t": "名词", "m": "ngọc thạch", "coll": "一块玉、玉做的手镯", "s": "奶奶送给她一个用玉做的手镯。"}, {"id": 19, "w": "壶", "p": "hú", "t": "名词", "m": "ấm, bình", "coll": "一壶茶、一把茶壶", "s": "客人来了，他立刻泡了一壶热茶。"}, {"id": 20, "w": "抢", "p": "qiǎng", "t": "动词", "m": "cướp, cướp đoạt", "coll": "抢走钱包、抢座位", "s": "上车的时候，请大家排好队，不要抢座位。"}, {"id": 21, "w": "埋", "p": "mái", "t": "动词", "m": "chôn", "coll": "埋在地下、埋进土里", "s": "孩子们把那只死去的小鸟埋在了树下。"}, {"id": 22, "w": "躲藏", "p": "duǒcáng", "t": "动词", "m": "giấu, ẩn núp", "coll": "躲藏起来、躲藏的地方", "s": "小猫躲藏在沙发后面，怎么也不肯出来。"}, {"id": 23, "w": "如今", "p": "rújīn", "t": "名词", "m": "ngày nay", "coll": "如今的生活、直到如今", "s": "如今，越来越多的人选择在网上学习。"}, {"id": 24, "w": "分布", "p": "fēnbù", "t": "动词", "m": "phân bố", "coll": "分布广泛、分布在各地", "s": "这些小商店分布在城市的不同地区。"}, {"id": 25, "w": "天然", "p": "tiānrán", "t": "形容词", "m": "tự nhiên, thiên nhiên", "coll": "天然的材料、天然食品", "s": "这家商店出售的肥皂主要使用天然的材料。"}, {"id": 26, "w": "优美", "p": "yōuměi", "t": "形容词", "m": "đẹp đẽ, tốt đẹp", "coll": "优美的风景、优美的旋律", "s": "湖边的风景十分优美，吸引了许多游客。"}, {"id": 27, "w": "独特", "p": "dútè", "t": "形容词", "m": "đặc biệt, riêng biệt", "coll": "独特的风格、独特的魅力", "s": "这位画家的作品有着非常独特的风格。"}, {"id": 28, "w": "反映", "p": "fǎnyìng", "t": "动词", "m": "phản ánh, thể hiện", "coll": "反映情况、反映生活", "s": "这部电影真实地反映了普通人的生活。"}, {"id": 29, "w": "珍珠", "p": "zhēnzhū", "t": "名词", "m": "ngọc trai, trân châu", "coll": "一颗珍珠、珍珠项链", "s": "她小心地拿起了那颗白色的珍珠。"}, {"id": 30, "w": "形成", "p": "xíngchéng", "t": "动词", "m": "hình thành", "coll": "形成习惯、逐渐形成", "s": "长期坚持阅读，有助于形成良好的学习习惯。"}, {"id": 31, "w": "于", "p": "yú", "t": "介词", "m": "từ, ở, vào", "coll": "生于、位于", "s": "这座博物馆位于城市的北部。"}, {"id": 32, "w": "广大", "p": "guǎngdà", "t": "形容词", "m": "rộng, rộng lớn", "coll": "广大读者、广大群众", "s": "这本书受到了广大读者的欢迎。"}, {"id": 33, "w": "岩石", "p": "yánshí", "t": "名词", "m": "nham thạch", "coll": "一块岩石、岩石表面", "s": "他坐在一块平坦的岩石上休息。"}, {"id": 34, "w": "亿", "p": "yì", "t": "数词", "m": "một trăm triệu", "coll": "一亿、数亿", "s": "这家公司的投资总额已经超过了一亿元。"}, {"id": 35, "w": "石灰岩", "p": "shíhuīyán", "t": "名词", "m": "đá vôi", "coll": "石灰岩样本、石灰岩地区", "s": "老师给我们展示了一块标着“石灰岩”的样本。"}, {"id": 36, "w": "地区", "p": "dìqū", "t": "名词", "m": "khu vực, vùng", "coll": "不同地区、沿海地区", "s": "不同地区的居民有着不同的生活习惯。"}, {"id": 37, "w": "表面", "p": "biǎomiàn", "t": "名词", "m": "bề mặt, phía ngoài", "coll": "物体表面、水的表面", "s": "请先把桌子表面的灰尘擦干净。"}, {"id": 38, "w": "角度", "p": "jiǎodù", "t": "名词", "m": "góc, độ của góc", "coll": "从不同角度、换个角度", "s": "我们应该从不同的角度看待这个问题。"}, {"id": 39, "w": "斜", "p": "xié", "t": "形容词", "m": "xiên, nghiêng", "coll": "有点儿斜、斜着放", "s": "墙上的画有点儿斜，请把它挂正。"}, {"id": 40, "w": "为", "p": "wéi", "t": "动词", "m": "trở thành", "coll": "成为、化为", "s": "经过多年的努力，这里已变为一座美丽的公园。"}, {"id": 41, "w": "火成岩", "p": "huǒchéngyán", "t": "名词", "m": "đá phun trào, đá mác-ma", "coll": "火成岩样本、一块火成岩", "s": "老师让我们仔细观察这块火成岩样本。"}, {"id": 42, "w": "碰", "p": "pèng", "t": "动词", "m": "đụng, gặp phải", "coll": "碰到桌角、碰了一下", "s": "他转身的时候，不小心碰到了桌角。"}, {"id": 43, "w": "挡", "p": "dǎng", "t": "动词", "m": "chặn, cản", "coll": "挡住去路、挡风", "s": "门口的那辆车挡住了大家的去路。"}, {"id": 44, "w": "地势", "p": "dìshì", "t": "名词", "m": "địa thế", "coll": "地势平坦、地势较高", "s": "这里地势比较平坦，很适合骑自行车。"}, {"id": 45, "w": "冲", "p": "chōng", "t": "动词", "m": "xông thẳng lên", "coll": "冲出教室、冲向终点", "s": "听到下课铃，孩子们高兴地冲出了教室。"}];
const CHUNKS=[["这座城市", "有着", "悠久的历史", "和丰富的文化。"], ["他", "用文字", "记录下了", "旅行中的见闻。"], ["这本书里", "详细记载了", "这座古城", "过去的生活。"], ["这些石头的形状", "各不相同，", "看起来", "很有意思。"], ["这篇文章", "生动地", "描写了", "春天的景色。"], ["这首歌", "表达了", "人们对家乡的", "赞美之情。"], ["她", "为", "自己的家乡", "写了一首诗。"], ["这项新政策", "给", "老百姓的生活", "带来了方便。"], ["节日的广场上", "充满了", "孩子们的", "笑声。"], ["对于", "你的帮助，", "我", "一直很感激。"], ["他", "调整了学习方法，", "从而", "提高了学习效率。"], ["这次旅行", "使我", "对当地的文化", "产生了兴趣。"], ["奶奶", "给我们", "讲了", "一个关于泉水的传说。"], ["她", "心地善良，", "经常", "帮助有困难的人。"], ["他", "毫不犹豫地", "跳进水里，", "救起了那个孩子。"], ["天气太热，", "他", "在路边", "晕了过去。"], ["这幅画上", "画着", "一条", "正在飞翔的龙。"], ["医生", "正在", "为受伤的病人", "进行治疗。"], ["奶奶", "送给她", "一个", "用玉做的手镯。"], ["客人来了，", "他", "立刻", "泡了一壶热茶。"], ["上车的时候，", "请大家", "排好队，", "不要抢座位。"], ["孩子们", "把", "那只死去的小鸟", "埋在了树下。"], ["小猫", "躲藏在", "沙发后面，", "怎么也不肯出来。"], ["如今，", "越来越多的人", "选择", "在网上学习。"], ["这些小商店", "分布在", "城市的", "不同地区。"], ["这家商店", "出售的肥皂", "主要使用", "天然的材料。"], ["湖边的风景", "十分优美，", "吸引了", "许多游客。"], ["这位画家的作品", "有着", "非常独特的", "风格。"], ["这部电影", "真实地", "反映了", "普通人的生活。"], ["她", "小心地", "拿起了", "那颗白色的珍珠。"], ["长期坚持阅读，", "有助于", "形成", "良好的学习习惯。"], ["这座博物馆", "位于", "城市的", "北部。"], ["这本书", "受到了", "广大读者的", "欢迎。"], ["他", "坐在", "一块平坦的岩石上", "休息。"], ["这家公司的投资总额", "已经", "超过了", "一亿元。"], ["老师", "给我们", "展示了", "一块标着“石灰岩”的样本。"], ["不同地区的居民", "有着", "不同的", "生活习惯。"], ["请", "先把", "桌子表面的灰尘", "擦干净。"], ["我们", "应该", "从不同的角度", "看待这个问题。"], ["墙上的画", "有点儿斜，", "请", "把它挂正。"], ["经过", "多年的努力，", "这里", "已变为一座美丽的公园。"], ["老师", "让我们", "仔细观察", "这块火成岩样本。"], ["他", "转身的时候，", "不小心", "碰到了桌角。"], ["门口的那辆车", "挡住了", "大家的", "去路。"], ["这里", "地势比较平坦，", "很适合", "骑自行车。"], ["听到下课铃，", "孩子们", "高兴地", "冲出了教室。"]];
'use strict';
const root=document.getElementById('ntc-design-preview');
const $=id=>document.getElementById(id);
const STORE='ngocthucac-hsk5-bai5-learning-v3';
const pages=['词汇表','学习生词','词汇卡片','综合练习','连词成句','学习统计'];
let storageOK=true,store={active:null,profiles:{}};
try{let raw=localStorage.getItem(STORE);if(raw){let parsed=JSON.parse(raw);if(parsed&&parsed.profiles)store=parsed}}catch(e){storageOK=false}
let student=store.active?store.profiles[store.active]:null;
if(!student){store.active='local';student=store.profiles.local||createStudent('','');store.profiles.local=student;}
let ui=student?.ui||{page:0,g:0,idx:0,pinyin:false};
let speed=1,playback=null,audioGeneration=0;
const group=g=>WORDS.slice(g*10,g===4?WORDS.length:g*10+10);
const groupOf=id=>Math.min(4,Math.floor(id/10));
const escapeHTML=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const hasLearned=id=>!!student?.studied.includes(id);
const learned=g=>group(g).filter(d=>hasLearned(d.id)).length;
const allLearned=()=>!!student&&student.studied.length===WORDS.length;
const memory=id=>student?.memory[id]||'new';
const weakIds=()=>WORDS.filter(d=>memory(d.id)==='review').map(d=>d.id);
const totalLearned=()=>student?.studied.length||0;
const currentWord=()=>group(ui.g)[ui.idx];
function shuffle(a){let b=[...a];for(let i=b.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b}
function toast(message){let t=$('ntc-toast');t.textContent=message;t.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.hidden=true,5000)}
function save(){if(student){student.ui={...ui};student.updatedAt=new Date().toISOString()}try{localStorage.setItem(STORE,JSON.stringify(store))}catch(e){storageOK=false;toast('浏览器无法保存学习进度，请允许保存本地数据。')}}
function createStudent(name,clas){return {name,clas,studied:[],memory:{},bookmark:{g:0,idx:0},ui:{page:0,g:0,idx:0,pinyin:false},flash:null,quiz:null,order:null,quizHistory:[],orderHistory:[],timeMs:0}}
function status(id){if(!hasLearned(id))return '<span class="ntc-state new">○ 未学习</span>';if(memory(id)==='review')return '<span class="ntc-state review">↻ 需要复习</span>';return '<span class="ntc-state">✓ 已学习</span>'}
function button(label,action,cls='',disabled=false){return `<button data-action="${action}" class="${cls}" ${disabled?'disabled':''}>${label}</button>`}
function go(page){stopAudio();ui.page=page;if(student&&allLearned()){if(page===2&&!student.flash)startFlash('all',false);if(page===3&&!student.quiz)startQuiz(false);if(page===4&&!student.order)startOrder(null,false)}save();render()}
function chooseGroup(g){stopAudio();ui.g=g;ui.idx=0;ui.page=1;save();render()}
function heading(title,subtitle='',tag=''){return `<div class="ntc-sectionhead"><div><h2>${title}</h2>${subtitle?`<p class="ntc-caption">${subtitle}</p>`:''}</div>${tag?`<span class="ntc-tag">${tag}</span>`:''}</div>`}
function meter(value,total){return `<div class="ntc-meter" role="progressbar" aria-label="进度" aria-valuenow="${value}" aria-valuemin="0" aria-valuemax="${total}"><span style="width:${total?value/total*100:0}%"></span></div>`}
function gate(){return `<div class="ntc-panel ntc-lock"><div class="ntc-kicker">先学习生词，再进行全课复习</div><h2>请先完成生词学习</h2><p>已学习 ${totalLearned()}/46 个词语。学完五组词语后，即可进行词汇卡片、综合练习和连词成句。</p>${meter(totalLearned(),46)}<div class="ntc-progressgroups">${[0,1,2,3,4].map(g=>`<button data-group="${g}">组别 ${g+1}<br>${learned(g)}/${group(g).length}个词语</button>`).join('')}</div>${button('继续学习 →','resume','ntc-primary')}</div>`}
function listView(){return `<div class="ntc-panel">${heading('词汇表','全课共46个词语，点击 ↗ 学习该词语',totalLearned()+'/46 已学习')}<div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>汉字</th><th class="ntc-colpinyin">拼音</th><th class="ntc-coltype">词性</th><th>越南语释义</th><th>状态</th></tr></thead><tbody>${WORDS.map((d,i)=>`<tr><td class="ntc-hanzi">${d.w} <button class="ntc-play" data-word="${i}" aria-label="学习词语 ${d.w}">↗</button><button class="ntc-play" data-audio-word="${i}" aria-label="听词语 ${d.w}">◖</button></td><td class="ntc-colpinyin">${escapeHTML(d.p)}</td><td class="ntc-coltype">${escapeHTML(d.t)}</td><td>${escapeHTML(d.m)}</td><td>${status(i)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-actions"><span class="ntc-caption">仅生词学习分为五组：10、10、10、10、6个词语。</span>${button('开始／继续学习 →','resume','ntc-primary')}</div></div>`}
function studyView(){let d=currentWord(),a=group(ui.g),isLast=d.id===45;return `<div class="ntc-panel">${heading('学习生词 · 组别 '+(ui.g+1),'学习词语、搭配与例句',`${ui.idx+1}/${a.length}`)}${meter(learned(ui.g),a.length)}<div class="ntc-study"><div class="ntc-wordbox"><div class="ntc-pinyin" style="visibility:${ui.pinyin?'visible':'hidden'}">${escapeHTML(d.p)}</div><div class="ntc-bigword ntc-writing" id="ntc-writing" aria-label="汉字笔顺">${d.w}</div><div class="ntc-meaning">${escapeHTML(d.m)}</div><span class="ntc-type">${escapeHTML(d.t)}</span><div class="ntc-smallbtns">${button('笔顺演示','strokes')}<button data-audio-word="${d.id}">◖ 听词语</button>${button(ui.pinyin?'隐藏拼音':'显示拼音','pinyin')}</div></div><div><div class="ntc-label">常用搭配</div><div class="ntc-cn">${escapeHTML(d.coll)}</div><hr><div class="ntc-label">例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><div class="ntc-smallbtns"><button data-audio-example="${d.id}">◖ 听例句</button></div><div class="ntc-note">${status(d.id)}</div></div></div><div class="ntc-actions">${button('← 上一个','prev-study','',d.id===0)}${button(isLast?'✓ 已学习 · 全课复习 →':ui.idx===a.length-1?'✓ 已学习 · 下一组 →':'✓ 已学习 · 下一个 →','mark-study','ntc-primary')}</div><div class="ntc-footnote">点击“已学习”记录学习进度。需要时，可点击“笔顺演示”查看汉字的书写顺序。</div></div>`}
function markStudy(){let d=currentWord();if(!student.studied.includes(d.id))student.studied.push(d.id);let next=WORDS.find(x=>!student.studied.includes(x.id));if(d.id<45){let id=d.id+1;ui.g=groupOf(id);ui.idx=id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx}}else if(!next){ui.page=2;student.bookmark={g:4,idx:5};if(!student.flash)startFlash('all',false)}else{ui.g=groupOf(next.id);ui.idx=next.id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx};toast('还有未学完的词语，请继续学习。')}save();render()}
function startFlash(filter='all',redraw=true){let ids=filter==='weak'?weakIds():WORDS.map(d=>d.id);if(!ids.length){toast('暂无需要复习的词语。');return}student.flash={filter,ids:shuffle(ids),at:0,flipped:false,ratings:{},done:false};save();if(redraw)render()}
function flashView(){let f=student.flash;if(f.done)f.done=false;let d=WORDS[f.ids[f.at]];return `<div class="ntc-panel">${heading('词汇卡片 · 全课复习',f.filter==='weak'?'复习练习中答错的词语':'全课46个词语随机排列，不分组',`${f.at+1}/${f.ids.length}`)}${meter(f.at+1,f.ids.length)}<div class="ntc-smallbtns" style="margin-bottom:16px">${button('重新打乱全课46个词语','flash-all')}${button('待复习词语 ('+weakIds().length+')','flash-weak','',!weakIds().length)}</div><div class="ntc-flash"><span class="ntc-label">${f.flipped?'背面':'正面'}</span>${f.flipped?`<span class="ntc-pinyin">${escapeHTML(d.p)}</span><span class="ntc-meaning">${escapeHTML(d.m)}</span><span class="ntc-type">${escapeHTML(d.t)}</span><small>${escapeHTML(d.coll)}</small><div class="ntc-note"><span class="ntc-cn">${escapeHTML(d.s)}</span><button class="ntc-play" data-audio-example="${d.id}" aria-label="听例句">◖</button></div>`:`<div style="display:flex;align-items:center;justify-content:center;gap:12px"><span class="ntc-bigword" style="font-size:clamp(40px,${d.w.length>2?'7':'10'}vw,${d.w.length>2?'80':'112'}px)">${d.w}</span><button class="ntc-play" data-audio-word="${d.id}" aria-label="听发音 ${d.w}" title="听发音">🔊</button></div>`}<div class="ntc-smallbtns">${button(f.flipped?'↶ 返回正面':'查看释义与例句 ↻','flip')}</div></div><div class="ntc-actions">${button('← 上一张','flash-prev','',f.at===0)}${f.at===f.ids.length-1?button('综合练习 →','quiz-page','ntc-primary'):button('下一张 →','flash-next','ntc-primary')}</div><div class="ntc-footnote">先看正面回忆词义；需要时翻到背面查看拼音、释义与例句。无需翻面即可切换卡片。</div></div>`}
const contextAlternatives={"0": [6, 16, 19], "1": [6, 16, 19], "2": [6, 16, 19], "3": [6, 16, 19], "4": [6, 16, 19], "5": [6, 16, 19], "6": [6, 16, 19], "7": [6, 16, 19], "8": [6, 16, 19], "9": [6, 16, 19], "10": [6, 16, 19], "11": [6, 16, 19], "12": [6, 16, 19], "13": [6, 16, 19], "14": [6, 16, 19], "15": [6, 16, 19], "16": [6, 16, 19], "17": [6, 16, 19], "18": [6, 16, 19], "19": [6, 16, 19], "20": [6, 16, 19], "21": [6, 16, 19], "22": [6, 16, 19], "23": [6, 16, 19], "24": [6, 16, 19], "25": [6, 16, 19], "26": [6, 16, 19], "27": [6, 16, 19], "28": [6, 16, 19], "29": [0, 10, 31], "30": [6, 16, 19], "31": [6, 16, 19], "32": [10, 31, 45], "33": [6, 16, 19], "34": [6, 16, 19], "35": [0, 10, 31], "36": [6, 16, 19], "37": [6, 16, 19], "38": [6, 16, 19], "39": [6, 16, 19], "40": [6, 16, 19], "41": [0, 10, 31], "42": [6, 16, 19], "43": [6, 16, 19], "44": [6, 16, 19], "45": [6, 16, 19]};
function makeQuestions(ids){let types=ids.map(id=>id%3===2?'context':id%3===0?'listen':'meaning');let positions=shuffle(ids.map((_,i)=>i%4));return shuffle(ids.map((id,i)=>{let alternatives=types[i]==='context'?contextAlternatives[id]:null;let opts=alternatives?shuffle(alternatives):shuffle(WORDS.filter(d=>d.id!==id).map(d=>d.id)).slice(0,3);opts.splice(positions[i],0,id);return {id,type:types[i],opts,correct:positions[i],picked:null}}))}
function startQuiz(redraw=true,ids=null){student.quiz={questions:makeQuestions(ids||WORDS.map(d=>d.id)),at:0,done:false,recorded:false};save();if(redraw)render()}
function quizView(){let q=student.quiz;if(q.done)return quizResults();let x=q.questions[q.at],d=WORDS[x.id],answered=x.picked!==null;return `<div class="ntc-panel">${heading('综合练习','听音选词 · 根据越南语释义选词 · 选词填空',`${q.at+1}/${q.questions.length}题`)}${meter(q.at,q.questions.length)}<div class="ntc-label">${x.type==='listen'?'听一听 · 听音选词':x.type==='meaning'?'认一认 · 根据越南语释义选词':'用一用 · 选词填空'}</div>${x.type==='listen'?`<button data-audio-word="${d.id}" class="ntc-primary">◖ 听词语</button><div class="ntc-footnote">如设备没有中文语音，可切换为根据越南语释义选词。</div>${button('切换为释义题','quiz-as-meaning','',answered)}`:x.type==='meaning'?`<div class="ntc-note">请根据越南语释义选择正确的汉语词语： <strong>${escapeHTML(d.m)}</strong></div>`:`<div class="ntc-cn">${escapeHTML(d.s.replace(d.w,'____'))}</div>`}<div class="ntc-quizopts">${x.opts.map((id,i)=>`<button data-answer="${i}" ${answered?'disabled':''} class="${answered?(i===x.correct?'ntc-correct':i===x.picked?'ntc-wrong':''):''}">${'ABCD'[i]}. ${WORDS[id].w}</button>`).join('')}</div>${answered?`<div class="ntc-note" role="status"><strong>${x.picked===x.correct?'✓ 正确':'✕ 不正确'}</strong><div class="ntc-cn">${d.w} · ${escapeHTML(d.p)}</div>${escapeHTML(d.m)}<br>${escapeHTML(d.s)}</div><div class="ntc-actions"><button data-audio-example="${d.id}">◖ 听例句</button>${button(q.at===q.questions.length-1?'查看结果 →':'下一题 →','quiz-next','ntc-primary')}</div>`:''}</div>`}
function pickQuiz(i){let q=student.quiz,x=q.questions[q.at];if(x.picked!==null)return;x.picked=i;if(i!==x.correct)student.memory[x.id]='review';save();render()}
function nextQuiz(){let q=student.quiz;if(q.questions[q.at].picked===null)return;if(q.at<q.questions.length-1)q.at++;else{q.done=true;if(!q.recorded){student.quizHistory.push({date:new Date().toISOString(),answers:q.questions.map(x=>({id:x.id,ok:x.picked===x.correct})),total:q.questions.length});q.recorded=true}}save();render()}
function quizResults(){let q=student.quiz,wrong=q.questions.filter(x=>x.picked!==x.correct),correct=q.questions.length-wrong.length;return `<div class="ntc-panel">${heading('综合练习结果','正确答案与待复习词语')}<div class="ntc-score">${correct}<small> / ${q.questions.length}题答对</small></div><div class="ntc-tag">${wrong.length}题答错</div>${wrong.map(x=>`<div class="ntc-miniresult"><strong>${WORDS[x.id].w}</strong> · ${escapeHTML(WORDS[x.id].p)}<br>你的选择： ${WORDS[x.opts[x.picked]].w}<br>正确释义： ${escapeHTML(WORDS[x.id].m)}<br>${escapeHTML(WORDS[x.id].s)}</div>`).join('')}<div class="ntc-actions">${button('重新练习全课词语','quiz-restart')}${button('重练错词','quiz-retry','',!wrong.length)}${button('连词成句 →','order-page','ntc-primary')}</div></div>`}
function startOrder(ids=null,redraw=true){let chosen=ids||WORDS.map(d=>d.id);student.order={ids:shuffle(chosen),at:0,bank:[],selected:[],checked:false,answers:[],done:false,recorded:false};newOrderQuestion();save();if(redraw)render()}
function newOrderQuestion(){let o=student.order;o.bank=shuffle(CHUNKS[o.ids[o.at]].map((_,i)=>i));if(o.bank.every((x,i)=>x===i))o.bank.reverse();o.selected=[];o.checked=false}
function orderView(){let o=student.order;if(o.done)return orderResults();let id=o.ids[o.at],d=WORDS[id],chunks=CHUNKS[id],ok=o.selected.every((x,i)=>x===i);return `<div class="ntc-panel">${heading('连词成句 · 全课复习','使用已学的46个例句，题目随机排列',`${o.at+1}/${o.ids.length}题`)}${meter(o.at,o.ids.length)}<div class="ntc-label">重点词语 · ${d.w}</div><p class="ntc-caption">按顺序选择词语，点击已选词语可将其放回。</p><div class="ntc-orderanswer ${o.checked?(ok?'ntc-correct':'ntc-wrong'):''}" aria-label="已排列的句子">${o.selected.length?o.selected.map((index,i)=>`<button data-remove="${i}" ${o.checked?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join(''):'<span class="ntc-caption">请在这里排列句子……</span>'}</div><div class="ntc-chunks" aria-label="待选词语">${o.bank.map(index=>`<button class="${o.selected.includes(index)?'used':''}" data-chunk="${index}" ${o.checked||o.selected.includes(index)?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join('')}</div><div class="ntc-actions"><div class="ntc-smallbtns">${button('↶ 撤销最后一项','order-undo','',!o.selected.length||o.checked)}${button('重新排列','order-clear','',!o.selected.length||o.checked)}</div>${button('检查答案','order-check','ntc-primary',o.selected.length!==chunks.length||o.checked)}</div>${o.checked?`<div class="ntc-note" role="status"><strong>${ok?'✓ 与例句顺序一致':'✕ 与例句顺序不一致'}</strong><div class="ntc-label">原例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><button data-audio-example="${id}">◖ 听例句</button></div><div class="ntc-actions"><span></span>${button(o.at===o.ids.length-1?'查看结果 →':'下一题 →','order-next','ntc-primary')}</div>`:''}<div class="ntc-footnote">本练习按原例句顺序评分，其他语序也可能符合语法。</div></div>`}
function addChunk(index){let o=student.order;if(o.checked||o.selected.includes(index))return;o.selected.push(index);save();render()}
function removeChunk(index){let o=student.order;if(o.checked)return;o.selected.splice(index,1);save();render()}
function checkOrder(){let o=student.order;if(o.checked||o.selected.length!==CHUNKS[o.ids[o.at]].length)return;o.checked=true;let id=o.ids[o.at],ok=o.selected.every((x,i)=>x===i);o.answers.push({id,ok});if(!ok)student.memory[id]='review';save();render()}
function nextOrder(){let o=student.order;if(!o.checked)return;if(o.at<o.ids.length-1){o.at++;newOrderQuestion()}else{o.done=true;if(!o.recorded){student.orderHistory.push({date:new Date().toISOString(),answers:o.answers.map(x=>({...x})),total:o.ids.length});o.recorded=true}}save();render()}
function orderResults(){let o=student.order,wrong=o.answers.filter(x=>!x.ok).map(x=>x.id),correct=o.answers.length-wrong.length;return `<div class="ntc-panel">${heading('连词成句结果','第5课综合复习')}<div class="ntc-score">${correct}<small> / ${o.answers.length}题答对</small></div><div class="ntc-tag">${wrong.length} 题需要重新练习</div>${wrong.map(id=>`<div class="ntc-miniresult"><strong>${WORDS[id].w}</strong><br><span class="ntc-cn">${escapeHTML(WORDS[id].s)}</span></div>`).join('')}<div class="ntc-actions">${button('重新练习全课句子','order-restart')}${button('重练错题','order-retry','',!wrong.length)}${button('查看学习统计 →','stats-page','ntc-primary')}</div></div>`}
function activityScore(kind,g){let history=kind==='quiz'?student.quizHistory:student.orderHistory,record=history[history.length-1],answers=record?.answers||[],ids=group(g).map(d=>d.id),inGroup=answers.filter(x=>ids.includes(x.id));let active=kind==='quiz'?student.quiz:student.order;if(active&&!active.done){let partial=kind==='quiz'?active.questions.filter(x=>x.picked!==null).map(x=>({id:x.id,ok:x.picked===x.correct})):active.answers;inGroup=partial.filter(x=>ids.includes(x.id));if(inGroup.length)return inGroup.filter(x=>x.ok).length+'/'+inGroup.length+' 进行中'}return inGroup.length?inGroup.filter(x=>x.ok).length+'/'+inGroup.length:'尚未练习'}
function statsView(){let weak=weakIds();return `<div class="ntc-panel">${heading('学习统计','当前浏览器中的第5课学习进度','第5课 · 46个词语')}<div class="ntc-statrow"><div class="ntc-stat"><label>已学词语</label><strong>${totalLearned()}<small> / 46</small></strong></div><div class="ntc-stat"><label>需要复习</label><strong>${weak.length}<small>个词语</small></strong></div></div><div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>组别</th><th>已学习</th><th>待复习</th><th>综合练习</th><th>连词成句</th></tr></thead><tbody>${[0,1,2,3,4].map(g=>`<tr><td>组别 ${g+1}<div class="ntc-caption">${group(g).length}个词语</div></td><td>${learned(g)}/${group(g).length}</td><td>${group(g).filter(d=>memory(d.id)==='review').length}</td><td>${activityScore('quiz',g)}</td><td>${activityScore('order',g)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-footnote">按词语所属组显示答对题数／已答题数。优先显示本轮进度，否则显示最近一轮结果。</div><hr><div class="ntc-sectionhead"><h2>待复习词语</h2>${button('用词汇卡片复习 →','flash-weak','',!weak.length||!allLearned())}</div><div class="ntc-terms">${weak.length?weak.map(id=>`<button data-word="${id}">${WORDS[id].w}</button>`).join(''):'<span class="ntc-caption">暂无需要复习的错词。</span>'}</div><div class="ntc-note">继续学习：组别 ${student.bookmark.g+1} · 词语 ${student.bookmark.idx+1}/${group(student.bookmark.g).length}.<br>本页累计学习时间约 ${Math.floor(student.timeMs/60000)} 分钟。已完成综合练习轮数： ${student.quizHistory.length}; 连词成句轮数： ${student.orderHistory.length}.</div><div class="ntc-actions">${button('继续学习','resume','ntc-primary')}${button('导出学习记录','backup')}${button('恢复学习记录','restore')}</div><div class="ntc-footnote">答错词语会列入待复习词语。浏览词汇卡片不等于掌握词语。</div></div>`}
function render(){clearWriting();let total=totalLearned();$('ntc-profile-button').textContent='HSK5 · 第5课';$('ntc-bookmark').textContent=student?total+'/46 个已学词语':'';$('ntc-tabs').innerHTML=pages.map((name,i)=>`<button class="ntc-tab ${ui.page===i?'active':''}" data-page="${i}" aria-pressed="${ui.page===i}">${i<5?i+1+'. ':''}${name}${i>=2&&i<=4&&!allLearned()?' 🔒':''}</button>`).join('');let showGroups=ui.page===1;$('ntc-groups').hidden=!showGroups;$('ntc-groups').innerHTML=showGroups?[0,1,2,3,4].map(g=>`<button data-group="${g}" class="${g===ui.g?'active':''}">组别 ${g+1} · ${group(g).length}个词语 · ${learned(g)}/${group(g).length}</button>`).join(''):'';$('ntc-sidegroups').innerHTML=showGroups?'<div class="ntc-navtitle">当前词汇组</div>'+[0,1,2,3,4].map(g=>`<button class="ntc-sidegroup ${g===ui.g?'active':''}" data-group="${g}"><span>组别 ${g+1}<br><small>词语 ${g*10+1}–${g*10+group(g).length}</small></span><small>${learned(g)}/${group(g).length}</small></button>`).join(''):'<div class="ntc-navtitle">第5课学习进度</div><div style="padding:0 10px">'+total+'/46 个已学词语'+meter(total,46)+'</div>';$('ntc-sidefoot').innerHTML='学完生词 →<br>全课综合复习。<br><br>进度保存在<br>当前浏览器中。';let html;if(ui.page>=2&&ui.page<=4&&!allLearned())html=gate();else html=[listView,studyView,flashView,quizView,orderView,statsView][ui.page]();$('ntc-view').innerHTML=html;if(ui.page===1)setupWriting();}
function stopAudio(){audioGeneration++;if(playback){playback.pause();playback=null}if('speechSynthesis' in window)window.speechSynthesis.cancel()}
const AUDIO_INDEX={"悠久":"data:audio/mpeg;base64,","这座城市有着悠久的历史和丰富的文化。":"data:audio/mpeg;base64,","文字":"data:audio/mpeg;base64,","他用文字记录下了旅行中的见闻。":"data:audio/mpeg;base64,","记载":"data:audio/mpeg;base64,","这本书里详细记载了这座古城过去的生活。":"data:audio/mpeg;base64,","形状":"data:audio/mpeg;base64,","这些石头的形状各不相同，看起来很有意思。":"data:audio/mpeg;base64,","描写":"data:audio/mpeg;base64,","这篇文章生动地描写了春天的景色。":"data:audio/mpeg;base64,","赞美":"data:audio/mpeg;base64,","这首歌表达了人们对家乡的赞美之情。":"data:audio/mpeg;base64,","诗":"data:audio/mpeg;base64,","她为自己的家乡写了一首诗。":"data:audio/mpeg;base64,","老百姓":"data:audio/mpeg;base64,","这项新政策给老百姓的生活带来了方便。":"data:audio/mpeg;base64,","充满":"data:audio/mpeg;base64,","节日的广场上充满了孩子们的笑声。":"data:audio/mpeg;base64,","感激":"data:audio/mpeg;base64,","对于你的帮助，我一直很感激。":"data:audio/mpeg;base64,","从而":"data:audio/mpeg;base64,","他调整了学习方法，从而提高了学习效率。":"data:audio/mpeg;base64,","产生":"data:audio/mpeg;base64,","这次旅行使我对当地的文化产生了兴趣。":"data:audio/mpeg;base64,","传说":"data:audio/mpeg;base64,","奶奶给我们讲了一个关于泉水的传说。":"data:audio/mpeg;base64,","善良":"data:audio/mpeg;base64,","她心地善良，经常帮助有困难的人。":"data:audio/mpeg;base64,","救":"data:audio/mpeg;base64,","他毫不犹豫地跳进水里，救起了那个孩子。":"data:audio/mpeg;base64,","晕":"data:audio/mpeg;base64,","天气太热，他在路边晕了过去。":"data:audio/mpeg;base64,","龙":"data:audio/mpeg;base64,","这幅画上画着一条正在飞翔的龙。":"data:audio/mpeg;base64,","治疗":"data:audio/mpeg;base64,","医生正在为受伤的病人进行治疗。":"data:audio/mpeg;base64,","玉":"data:audio/mpeg;base64,","奶奶送给她一个用玉做的手镯。":"data:audio/mpeg;base64,","壶":"data:audio/mpeg;base64,","客人来了，他立刻泡了一壶热茶。":"data:audio/mpeg;base64,","抢":"data:audio/mpeg;base64,","上车的时候，请大家排好队，不要抢座位。":"data:audio/mpeg;base64,","埋":"data:audio/mpeg;base64,","孩子们把那只死去的小鸟埋在了树下。":"data:audio/mpeg;base64,","躲藏":"data:audio/mpeg;base64,","小猫躲藏在沙发后面，怎么也不肯出来。":"data:audio/mpeg;base64,","如今":"data:audio/mpeg;base64,","如今，越来越多的人选择在网上学习。":"data:audio/mpeg;base64,","分布":"data:audio/mpeg;base64,","这些小商店分布在城市的不同地区。":"data:audio/mpeg;base64,","天然":"data:audio/mpeg;base64,","这家商店出售的肥皂主要使用天然的材料。":"data:audio/mpeg;base64,","优美":"data:audio/mpeg;base64,","湖边的风景十分优美，吸引了许多游客。":"data:audio/mpeg;base64,","独特":"data:audio/mpeg;base64,","这位画家的作品有着非常独特的风格。":"data:audio/mpeg;base64,","反映":"data:audio/mpeg;base64,","这部电影真实地反映了普通人的生活。":"data:audio/mpeg;base64,","珍珠":"data:audio/mpeg;base64,","她小心地拿起了那颗白色的珍珠。":"data:audio/mpeg;base64,","形成":"data:audio/mpeg;base64,","长期坚持阅读，有助于形成良好的学习习惯。":"data:audio/mpeg;base64,","于":"data:audio/mpeg;base64,","这座博物馆位于城市的北部。":"data:audio/mpeg;base64,","广大":"data:audio/mpeg;base64,","这本书受到了广大读者的欢迎。":"data:audio/mpeg;base64,","岩石":"data:audio/mpeg;base64,","他坐在一块平坦的岩石上休息。":"data:audio/mpeg;base64,","亿":"data:audio/mpeg;base64,","这家公司的投资总额已经超过了一亿元。":"data:audio/mpeg;base64,","石灰岩":"data:audio/mpeg;base64,","老师给我们展示了一块标着“石灰岩”的样本。":"data:audio/mpeg;base64,","地区":"data:audio/mpeg;base64,","不同地区的居民有着不同的生活习惯。":"data:audio/mpeg;base64,","表面":"data:audio/mpeg;base64,","请先把桌子表面的灰尘擦干净。":"data:audio/mpeg;base64,","角度":"data:audio/mpeg;base64,","我们应该从不同的角度看待这个问题。":"data:audio/mpeg;base64,","斜":"data:audio/mpeg;base64,","墙上的画有点儿斜，请把它挂正。":"data:audio/mpeg;base64,","为":"data:audio/mpeg;base64,","经过多年的努力，这里已变为一座美丽的公园。":"data:audio/mpeg;base64,","火成岩":"data:audio/mpeg;base64,","老师让我们仔细观察这块火成岩样本。":"data:audio/mpeg;base64,","碰":"data:audio/mpeg;base64,","他转身的时候，不小心碰到了桌角。":"data:audio/mpeg;base64,","挡":"data:audio/mpeg;base64,","门口的那辆车挡住了大家的去路。":"data:audio/mpeg;base64,","地势":"data:audio/mpeg;base64,","这里地势比较平坦，很适合骑自行车。":"data:audio/mpeg;base64,","冲":"data:audio/mpeg;base64,","听到下课铃，孩子们高兴地冲出了教室。":"data:audio/mpeg;base64,"};
function speak(text){stopAudio();const path=AUDIO_INDEX[text];if(!path){toast('未找到此内容的配套音频。');return}const generation=audioGeneration;const player=new Audio(path);playback=player;player.playbackRate=speed;player.onerror=()=>{if(generation===audioGeneration){$('ntc-voice-label').textContent='音频未加载';toast('无法加载音频，请确认 HTML 与 audio 文件夹一起保存或上传。')}};player.onended=()=>{if(playback===player)playback=null};player.play().then(()=>{if(generation!==audioGeneration){player.pause();return}$('ntc-voice-label').textContent='朗读：Xiaoxiao · 固定 MP3';}).catch(()=>{if(generation===audioGeneration)toast('音频暂时无法播放，请确认音频文件存在后再次点击。')})}
function backup(){const content=JSON.stringify({format:'ntc-hsk5-bai5-v3',profile:student},null,2);let url=URL.createObjectURL(new Blob([content],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='HSK5_Bai5_TienDo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function restore(){let input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.addEventListener('change',async()=>{try{let v=JSON.parse(await input.files[0].text()),p=v.profile;if(v.format!=='ntc-hsk5-bai5-v3'||!p||typeof p.name!=='string'||typeof p.clas!=='string'||!Array.isArray(p.studied)||p.studied.some(id=>!Number.isInteger(id)||id<0||id>=46)||!p.memory)throw Error();if(!confirm('恢复第5课学习记录？当前记录将被替换。'))return;let id=store.active||'local';let clean=createStudent(p.name,p.clas);clean.studied=[...new Set(p.studied)];for(let k=0;k<46;k++)if(['remembered','review'].includes(p.memory[k]))clean.memory[k]=p.memory[k];if(p.bookmark&&Number.isInteger(p.bookmark.g)&&p.bookmark.g>=0&&p.bookmark.g<5&&Number.isInteger(p.bookmark.idx)&&p.bookmark.idx>=0&&p.bookmark.idx<group(p.bookmark.g).length)clean.bookmark=p.bookmark;for(let key of ['quizHistory','orderHistory'])if(Array.isArray(p[key]))clean[key]=p[key].filter(r=>r&&Array.isArray(r.answers)&&r.answers.every(a=>Number.isInteger(a.id)&&a.id>=0&&a.id<46&&typeof a.ok==='boolean'));clean.timeMs=Math.max(0,Number(p.timeMs)||0);store.profiles[id]=clean;store.active=id;student=clean;ui={page:5,g:0,idx:0,pinyin:false};save();render();toast('已恢复已学词语、复习状态与练习记录。')}catch(e){toast('无法读取有效的HSK5第5课学习记录。')}});input.click()}
root.addEventListener('click',event=>{let b=event.target.closest('button');if(!b||b.disabled)return;const data=b.dataset;if(data.audioWord!==undefined){speak(WORDS[+data.audioWord].w);return}if(data.audioExample!==undefined){speak(WORDS[+data.audioExample].s);return}if(data.page!==undefined){go(+data.page);return}if(data.group!==undefined){chooseGroup(+data.group);return}if(data.word!==undefined){let id=+data.word;ui.g=groupOf(id);ui.idx=id-ui.g*10;go(1);return}if(data.answer!==undefined){stopAudio();pickQuiz(+data.answer);return}if(data.chunk!==undefined){addChunk(+data.chunk);return}if(data.remove!==undefined){removeChunk(+data.remove);return}let a=data.action;if(!a)return;if(a==='stop'){stopAudio();return}switch(a){case'strokes':animateWriting();return;case'resume':ui.g=student.bookmark.g;ui.idx=student.bookmark.idx;go(1);return;case'pinyin':ui.pinyin=!ui.pinyin;break;case'prev-study':{let id=currentWord().id-1;ui.g=groupOf(id);ui.idx=id-ui.g*10;break}case'mark-study':stopAudio();markStudy();return;case'flip':student.flash.flipped=!student.flash.flipped;break;case'flash-all':if(!allLearned()){go(2);return}ui.page=2;startFlash('all');return;case'flash-weak':if(!allLearned()){go(2);return}ui.page=2;startFlash('weak');return;case'flash-prev':student.flash.at--;student.flash.flipped=false;break;case'flash-next':student.flash.at++;student.flash.flipped=false;break;case'quiz-page':go(3);return;case'order-page':go(4);return;case'stats-page':go(5);return;case'quiz-as-meaning':student.quiz.questions[student.quiz.at].type='meaning';break;case'quiz-next':stopAudio();nextQuiz();return;case'quiz-restart':startQuiz();return;case'quiz-retry':startQuiz(true,student.quiz.questions.filter(x=>x.picked!==x.correct).map(x=>x.id));return;case'order-undo':removeChunk(student.order.selected.length-1);return;case'order-clear':student.order.selected=[];break;case'order-check':checkOrder();return;case'order-next':stopAudio();nextOrder();return;case'order-restart':startOrder();return;case'order-retry':startOrder(student.order.answers.filter(x=>!x.ok).map(x=>x.id));return;case'backup':backup();return;case'restore':restore();return;default:return}save();render()});
root.addEventListener('change',event=>{if(event.target.id==='ntc-rate')speed=Number(event.target.value)});


let strokeWriters=[],strokeRun=0;
function clearWriting(){strokeRun++;for(const w of strokeWriters){w.pauseAnimation();}strokeWriters=[];}
function setupWriting(){const box=$('ntc-writing');if(!box)return;box.innerHTML='';for(const c of currentWord().w){const el=document.createElement('span');el.setAttribute('aria-label',c);box.appendChild(el);if(!STROKE_DATA[c]||typeof HanziWriter==='undefined'){el.textContent=c;continue;}strokeWriters.push(HanziWriter.create(el,c,{width:92,height:106,padding:3,strokeColor:'#a3455d',radicalColor:'#a3455d',outlineColor:'#ecd2db',strokeAnimationSpeed:0.7,delayBetweenStrokes:180,charDataLoader:()=>STROKE_DATA[c]}));}}
async function animateWriting(){const token=++strokeRun,list=[...strokeWriters];if(!list.length){toast('暂时无法显示笔顺。');return;}const button=root.querySelector('[data-action="strokes"]');if(button)button.disabled=true;try{for(const w of list)await w.hideCharacter({duration:0});for(const w of list){if(token!==strokeRun)return;await w.animateCharacter();}}finally{if(token===strokeRun&&button)button.disabled=false;}}

let lastTick=Date.now();setInterval(()=>{let now=Date.now();if(student&&!document.hidden){student.timeMs+=Math.min(now-lastTick,15000);save()}lastTick=now},15000);
window.addEventListener('pagehide',()=>{save();stopAudio()});
if(student&&ui.page>=2&&ui.page<=4&&allLearned()){if(ui.page===2&&!student.flash)startFlash('all',false);if(ui.page===3&&!student.quiz)startQuiz(false);if(ui.page===4&&!student.order)startOrder(null,false)}
save();render();if(!storageOK)toast('浏览器阻止保存数据，建议导出学习记录作为备份。');

